"use strict";
GUIDE_DATA_EN.sections.push({"id":"g0","part":0,"title":"Introduction","blocks":[{"level":1,"text":"Project+ gives IT professionals the basic concepts to successfully manage small to medium sized projects"},{"level":1,"text":"This certification will verify the successful candidate has the knowledge and skills required to the following"},{"level":2,"text":"Manage the project life cycle"},{"level":2,"text":"Coordinate small-to-medium sized projects"},{"level":2,"text":"Communication plan"},{"level":2,"text":"Resources and stakeholders"},{"level":2,"text":"Project documentation"},{"level":2,"text":"Completion of larger projects"},{"level":1,"text":"The certification will also cover both waterfall and agile project management methodologies"},{"level":1,"text":"Project Management"},{"level":2,"text":"The practice of initiating, planning, executing, controlling, and closing the work of a team to achieve specific goals and meet specific success criteria at the specified time"},{"level":1,"text":"The exam you will take to become certified has a maximum of 90 questions over the course of 90 minutes"},{"level":2,"text":"Multiple-choice questions"},{"level":2,"text":"3 to 5 performance-based questions"},{"level":1,"text":"The exam covers four domains"},{"level":2,"text":"Project Management Concepts (33%)"},{"level":2,"text":"Project Life Cycle Phases (30%)"},{"level":2,"text":"Tools and Documentation (19%)"},{"level":2,"text":"Basics of IT and Governance (18%)"},{"level":1,"text":"4 tips for success in this course"},{"level":2,"text":"Turn on closed captioning"},{"level":2,"text":"If you want to enable closed captions, simply click on the CC button in the bottom of your video player"},{"level":2,"text":"You can control the playback speed"},{"level":2,"text":"Faster or slower, the choice is yours"},{"level":2,"text":"Join our student support group"},{"level":2,"text":"www.facebook.com/groups/diontraining"},{"level":2,"text":"In this group, we answer your questions, we put out additional free content, and we help support each other throughout our IT careers"},{"level":2,"text":"Download and print the study guide"},{"level":2,"text":"We do recommend you download it, print it out, highlight on it, circle on it, take notes directly on it, whatever you need to do so you have it ready to reference during your offline studies before taking the exam"}]},{"id":"g1","part":0,"title":"Exam Tips","blocks":[{"level":1,"text":"There will be no trick questions"},{"level":2,"text":"Always be on the lookout for distractors or red herrings"},{"level":2,"text":"At least one of the four listed possible answer choices that are written to try and distract you from the correct answer"},{"level":1,"text":"Pay close attention to words in bold, italics, or all uppercase"},{"level":1,"text":"Answer the questions based on CompTIA Project+ knowledge"},{"level":2,"text":"In the world of project management, there is often not a 100% correct answer to every question you face in your daily work"},{"level":2,"text":"When in doubt, choose the answer that is correct for the highest number of situations"},{"level":1,"text":"Understand the key concepts of the test questions"},{"level":1,"text":"Do not memorize the terms word for word, try to understand them instead"},{"level":1,"text":"During the exam, the answers will be from multiple-choice style questions"}]},{"id":"g2","part":0,"title":"100% Pass Guarantee","blocks":[{"level":1,"text":"All the risk is on us, as it should be"},{"level":2,"text":"You have nothing to lose here, but you do have to do your part and put in some effort"},{"level":1,"text":"When you take those quizzes, you have to score at least an 80% for it to be considered a pass in our system"},{"level":1,"text":"At the end of the course, you will find our practice exams"},{"level":2,"text":"Understand why the answers are right or wrong"},{"level":2,"text":"Explanations are provided for every single question"},{"level":1,"text":"Please don’t try to simply memorize the questions, but instead take the time to understand the why behind them"},{"level":1,"text":"Make sure that you watched the videos, took the quizzes, did the labs, and finished the practice exams"},{"level":2,"text":"If you’ve done all and don’t see the progress part at the top going from 0 to 100, that means something’s wrong"},{"level":2,"text":"If you think you’ve done everything and it still doesn’t show 100%, please email us at support@diontraining.com"},{"level":1,"text":"Once you have the course completion letter, you are eligible for our 60-Day 100% Pass Guarantee"}]},{"id":"g3","part":1,"title":"Project Lifecycle","blocks":[{"level":1,"text":"Project Management"},{"level":2,"text":"Practice of initiating, planning, executing, controlling, and closing a team's work to achieve specific goals and meet specific success criteria within a specified timeframe"},{"level":1,"text":"Having a good framework and methodology for project management helps everyone"},{"level":1,"text":"Project management lets the team save time, spend less money, and minimize the overall risk of a project"},{"level":1,"text":"Project"},{"level":2,"text":"Temporary organization created for the purpose of delivering one or more business products according to an agreed-upon business case"},{"level":2,"text":"Projects are temporary in nature"},{"level":2,"text":"It must have a defined beginning and end"},{"level":1,"text":"Business as Usual"},{"level":2,"text":"Standard and typical business operations"},{"level":1,"text":"A project follows a life cycle that starts with a business case and ideally ends with a successfully delivered project"},{"level":1,"text":"All projects move through five general phases of work"},{"level":2,"text":"Discovery Phase"},{"level":2,"text":"This occurs before the project starts"},{"level":2,"text":"Leaders and analysts brainstorm ideas for potential projects and determine whether they are practical for their organizations"},{"level":2,"text":"Initiation Phase"},{"level":2,"text":"You will learn about the project’s goals, what the project needs to deliver, and what the final product or outputs may look like"},{"level":2,"text":"This phase also builds the project team, where each member’s role is identified"},{"level":2,"text":"In the initiation phase, the project team is built, and roles are identified"},{"level":2,"text":"Planning Phase"},{"level":2,"text":"A high-level summary of the project’s goals is fully detailed and fleshed out"},{"level":2,"text":"Execution Phase"},{"level":2,"text":"This work varies by project and by the team"},{"level":2,"text":"By the end of the execution phase, the team has completed the plan, and as a result, all goals set in the initiation stage should be completed"},{"level":2,"text":"Closing Phase"},{"level":2,"text":"The project winds down and then end"},{"level":2,"text":"Products are delivered, billing accounts are closed to prevent accidental charges, feedback is provided, and lessons are recorded Project Management Basics"}]},{"id":"g4","part":1,"title":"Project Management Basics","blocks":[{"level":1,"text":"Projects are temporary in nature and are undertaken to produce a specific outcome within a specified amount of time"},{"level":1,"text":"Project management helps companies to meet their goals and objectives"},{"level":1,"text":"A project should be providing new value and not simply performing normal operations in a business"},{"level":1,"text":"Projects can last from a single day in duration to several years"},{"level":1,"text":"Project management turns an idea into a tangible goal and implements it"},{"level":2,"text":"It also controls costs while producing high-quality outcomes"},{"level":1,"text":"As a discipline, project management wants to deliver work in an orderly and efficient manner"},{"level":1,"text":"Templates make work easier and simplify the creation of project artifacts"}]},{"id":"g5","part":1,"title":"Project Management Skills","blocks":[{"level":1,"text":"Project management requires a mindset where adaptability, discipline, and personal relationships hold the same value"},{"level":1,"text":"A project manager needs to know the myriad of moving parts within a project"},{"level":1,"text":"Project teams have to stay flexible and adapt to the challenges that they face"},{"level":1,"text":"Project management also needs a fair amount of critical thinking, analysis, and problem-solving"},{"level":1,"text":"Project teams often work in areas where they do not own the systems or manage the people"},{"level":1,"text":"Project team members have—or develop—excellent collaboration, leadership, and influence skills"},{"level":1,"text":"Project management is a mosaic of different talents, and you will learn many valuable skills"}]},{"id":"g6","part":1,"title":"Benefits of Project Management","blocks":[{"level":1,"text":"Project Management"},{"level":2,"text":"It is designed to deliver work in an efficient, orderly manner"},{"level":1,"text":"Conducting good project management can save money and optimize the results for an organization"},{"level":1,"text":"Project management and project managers help bring order to complex work"},{"level":1,"text":"When managing a project, plans can change"},{"level":1,"text":"Contingency Reserve"},{"level":2,"text":"Calculated buffer of time and money that covers documented risks"},{"level":1,"text":"Management Reserve"},{"level":2,"text":"Additional sum of time or money that covers “unknown unknowns” - the setbacks we haven’t forecasted"},{"level":1,"text":"Benefits of properly conducting project management includes saving money, optimizing results, and preventing costly errors for organizations"}]},{"id":"g7","part":1,"title":"Types of Work","blocks":[{"level":1,"text":"The work environment surrounding an individual project influences the approach of the project and responsibilities of a project manager"},{"level":1,"text":"The roles, types of work, and organizational structure have an effect on communication, team dynamics, and reporting relationships"},{"level":1,"text":"2 Main Categories of Project Work"},{"level":2,"text":"Operational Work"},{"level":2,"text":"A routine, predictable, and repetitive work"},{"level":2,"text":"Project Work"},{"level":2,"text":"Accomplishes something new"},{"level":2,"text":"A project must meet three criteria"},{"level":2,"text":"It is unique"},{"level":2,"text":"It has a brand-new objective"},{"level":2,"text":"It has a specific purpose"},{"level":2,"text":"It has a reason to exist"},{"level":2,"text":"It is temporary"},{"level":2,"text":"It has a defined beginning and end"},{"level":1,"text":"Projects are a temporary endeavor"}]},{"id":"g8","part":1,"title":"Organizational Structures","blocks":[{"level":1,"text":"The organizational structure affects the project management process, how work moves, how people form teams, and the project manager's role"},{"level":1,"text":"3 Main Organizational Structure"},{"level":2,"text":"Functional"},{"level":2,"text":"Divides the organization into areas of specialization and expertise"},{"level":2,"text":"An organizational chart for this type of structure is pretty intuitive"},{"level":2,"text":"The functional manager is responsible for maintaining the budget and managing personnel"},{"level":2,"text":"The project manager coordinates the project"},{"level":2,"text":"Functional teams have less awareness of others in the organization, operating in information silos"},{"level":2,"text":"Projectized"},{"level":2,"text":"The organization pools resources around projects as its main focus"},{"level":2,"text":"Projectized organizations benefit companies that spend most of their resources on project work"},{"level":2,"text":"The project managers have more control in a projectized organization"},{"level":2,"text":"The project manager also owns the budget and typical line manager's responsibilities"},{"level":2,"text":"Matrix"},{"level":2,"text":"Includes both functional leaders and specialized roles"},{"level":2,"text":"In a matrix organization, the team members from the functional areas work on the project teams, either part-time or full-time"},{"level":2,"text":"2 Categories of Matrix Organization"},{"level":2,"text":"Weak Matrix Organization"},{"level":2,"text":"The functional manager retains budget and staff management responsibilities"},{"level":2,"text":"The project manager has a bit less control authority over the project"},{"level":2,"text":"Strong Matrix Organization"},{"level":2,"text":"The project manager has substantial control over the project"},{"level":2,"text":"They have both management responsibility for the staff and budget"},{"level":2,"text":"Businesses in nearly every industry can operate as a matrix organization"},{"level":2,"text":"The primary disadvantage of this type of structure is that employees often divide their time between operational work and one or more projects"}]},{"id":"g9","part":1,"title":"Roles and Responsibilities","blocks":[{"level":1,"text":"Project Manager"},{"level":2,"text":"Responsible for planning, organizing, leading, and keeping your teams on track and within budget"},{"level":2,"text":"Project managers are there to deliver projects on time, within budget, and within scope"},{"level":1,"text":"Program Manager"},{"level":2,"text":"Individuals that lead programs or related groups of projects"},{"level":2,"text":"A program manager operates at a more strategic level and oversees multiple projects in a program"},{"level":2,"text":"As a project manager, it is important to maintain communication with the program manager"},{"level":1,"text":"Project Management Office (PMO)"},{"level":2,"text":"Functional department for all project managers in a company"},{"level":2,"text":"Manages the flow of projects and provides administrative support, such as maintaining archives, best practices, and project management tools"},{"level":2,"text":"Oversees project performance management and tracks metrics for projects throughout the organization"},{"level":2,"text":"Provides valuable coaching and training for personnel"},{"level":2,"text":"3 Project Management Office Types"},{"level":2,"text":"Supportive Project Management Office"},{"level":2,"text":"Provides support when it is requested"},{"level":2,"text":"Controlling Project Management Office"},{"level":2,"text":"Monitors project performance and coordinates resource selection while allocating project managers to projects"},{"level":2,"text":"The controlling PMO coordinates communications and sets some project standards"},{"level":2,"text":"Directive Project Management Office"},{"level":2,"text":"Has full authority over projects, standards, and procedures"},{"level":2,"text":"It focuses on organizational strategy and will start, cancel, or adjust projects to ensure strategic alignment"},{"level":2,"text":"The PMO is motivated to ensure projects perform well, and every project lists the PMO as a stakeholder"},{"level":1,"text":"Some project influencer roles"},{"level":2,"text":"Stakeholder"},{"level":2,"text":"Anyone with a vested interest in the project"},{"level":2,"text":"Stakeholders are not built-in supporters"},{"level":2,"text":"Senior Management"},{"level":2,"text":"Highest level of leadership in an organization"},{"level":2,"text":"Sponsor"},{"level":2,"text":"A single senior management member that reviews and validates initial business case"},{"level":2,"text":"Secure funding and remove barriers, making them valuable assets for a project manager"},{"level":2,"text":"Customers"},{"level":2,"text":"Parties who receive the benefits from the projects"},{"level":2,"text":"Internal Customers"},{"level":2,"text":"Inside the organization"},{"level":2,"text":"They are more accessible to provide feedback during and after the project"},{"level":2,"text":"External Customers"},{"level":2,"text":"Outside the organization"},{"level":2,"text":"They may fund the project’s results"},{"level":2,"text":"End-User"},{"level":2,"text":"Person who will interact with the project’s final output"},{"level":2,"text":"The sponsor, customer, and end-user could be the same person in some instances"}]},{"id":"g10","part":1,"title":"Programs and Portfolios","blocks":[{"level":1,"text":"Each project has a single objective that explains what it intends to accomplish"},{"level":1,"text":"When a project is in a program, it increases the responsibilities of the project manager"},{"level":1,"text":"A project manager needs to be aware of other projects in the program and assess how any program changes affect the project’s schedule and scope"},{"level":1,"text":"Program stakeholders and program staff are stakeholders you will need to consider when assessing impacts"},{"level":1,"text":"There are budget constraints and other resource limits that must be accounted for"},{"level":2,"text":"To avoid this, use portfolios and portfolio management"},{"level":2,"text":"Program"},{"level":2,"text":"Group of related projects"},{"level":2,"text":"Portfolio"},{"level":2,"text":"Group of all projects and programs"},{"level":2,"text":"Projects in a program are related to the same objective, but projects in a portfolio do not need to be related"},{"level":2,"text":"Enterprise Portfolio"},{"level":2,"text":"Contains all programs and projects in an organization and is broken down into sub-portfolios at the division or branch level"},{"level":2,"text":"Portfolio Management"},{"level":2,"text":"Offers strategic context and perspective that helps an organization to maintain a maximum number of projects and prioritize them into objectives or priorities"},{"level":2,"text":"A successful portfolio management process limits the total number of projects"},{"level":1,"text":"Projects can be a part of larger programs and portfolios"},{"level":1,"text":"A program groups together related projects to achieve a larger objective"},{"level":1,"text":"Portfolio helps organizations prioritize and execute multiple projects and programs efficiently The Business Case"}]},{"id":"g11","part":2,"title":"The Business Case","blocks":[{"level":1,"text":"Business case is the most important part of why projects are undertaken"},{"level":2,"text":"It should be concise, visually appealing, and easy to read"},{"level":2,"text":"It is also called a “business justification” or “business objective”"},{"level":2,"text":"It summarizes information about the project and serves as the first project proposal"},{"level":1,"text":"A business case presents an objective analysis of a business problem, potential solutions, and financial impact"},{"level":1,"text":"Business case can contain any relevant data such as"},{"level":2,"text":"Executive Summary"},{"level":2,"text":"A brief synopsis of what the remaining portions of the business case will cover"},{"level":2,"text":"This is an overview of the most important relevant information, usually only a few sentences in length, that includes"},{"level":2,"text":"Problem Statement"},{"level":2,"text":"Solution"},{"level":2,"text":"Expected Result"},{"level":2,"text":"Problem Statement"},{"level":2,"text":"Shares more details about the problem"},{"level":2,"text":"The problem is then broken down in the problem analysis section"},{"level":2,"text":"It provides more context about why the project should be prioritized and may include evidence to support the following"},{"level":2,"text":"Business Case"},{"level":2,"text":"Environmental Assessment"},{"level":2,"text":"Historical Data"},{"level":2,"text":"Options"},{"level":2,"text":"Compare the solutions against each other with pros and cons"},{"level":2,"text":"Alternative identification adds more depth to the business case"},{"level":2,"text":"Financial Overview"},{"level":2,"text":"Contains a cost-benefit or return on investment analysis and provides relevant risks and assumptions"},{"level":2,"text":"Project Definition"},{"level":2,"text":"Additional relevant information about the proposed project"},{"level":2,"text":"Project Scope"},{"level":2,"text":"Resources"},{"level":2,"text":"Milestones"},{"level":2,"text":"Implementation Timeline"},{"level":2,"text":"Project Recommendation"},{"level":2,"text":"Provides an analysis of which option would likely be the best solution for the project"},{"level":2,"text":"It should reflect the Financial Overview, Return on Investment, and Project Definition"},{"level":1,"text":"Writing value-focused problem statements"},{"level":2,"text":"One of the primary goals of a project manager is to create a business case that resonates with stakeholders and concentrates on the value of the project instead of the technology"},{"level":2,"text":"Technology is simply a tool or vector that solves a problem for the business"},{"level":1,"text":"A good business case presents a problem and an expected outcome with multiple options"},{"level":1,"text":"Write the case using clear and simple language"},{"level":1,"text":"ESG (Environmental, Social, and Governance) Factors"},{"level":2,"text":"Refer to a company’s actions and programs beyond maximizing profits"}]},{"id":"g12","part":2,"title":"Current State and Future State","blocks":[{"level":1,"text":"A business case needs an element of storytelling"},{"level":1,"text":"Current State"},{"level":2,"text":"What is going on with the organization right now?"},{"level":1,"text":"Future State"},{"level":2,"text":"What the business is going to look like after implementing your project?"},{"level":1,"text":"A great comparison shows a clear difference between the current and future states of the organization"},{"level":1,"text":"Side-by-side comparisons can be visual, descriptive, or both and it will help hammer the points home"},{"level":1,"text":"A descriptive summary could slightly expand this information with qualitative improvements or unique investments"},{"level":2,"text":"A visual summary can also be included"},{"level":2,"text":"Visual summaries use diagrams or charts to show the differences between states"},{"level":1,"text":"Process Flowchart"},{"level":2,"text":"Shows the steps, sequence, and possible outcomes using a standard set of shapes"},{"level":1,"text":"To create a compelling visual comparison, you could create a current state, then cross out the steps that will be eliminated"},{"level":1,"text":"The future state would show a streamlined process flowchart, with fewer steps and less looping"},{"level":1,"text":"Be good storytellers when writing our business case"},{"level":1,"text":"Your current and future states should share the same metrics, and side-by-side comparisons can be used"}]},{"id":"g13","part":2,"title":"Financial Impact","blocks":[{"level":1,"text":"Financial Analysis"},{"level":2,"text":"Also called financial benefit, cost-benefit analysis, or an economic return"},{"level":1,"text":"Return on Investment (ROI)"},{"level":2,"text":"Compares the financial benefit of the project to the cost, and it is written as a percentage"},{"level":2,"text":"Positive number represents a profitable project"},{"level":2,"text":"Negative number means the project lost money"},{"level":2,"text":"ROI is often presented in the following three formulas which will all generate the same result"},{"level":2,"text":"ROI = (Net Profit / Cost) x 100"},{"level":2,"text":"ROI = ((Revenue – Cost) / Cost) x 100"},{"level":2,"text":"ROI = ((Financial Value – Project Cost) / Project Cost) x 100"},{"level":2,"text":"The three main values are the benefit, the cost, and the net profit"},{"level":2,"text":"Benefit"},{"level":2,"text":"The money generated or explicitly saved due to undertaking the project"},{"level":2,"text":"Benefit is often referred to as “financial value” or “revenue”"},{"level":2,"text":"This variable is the money flowing into the company"},{"level":2,"text":"Revenues"},{"level":2,"text":"Cost Reduction"},{"level":2,"text":"Cost Avoidance"},{"level":2,"text":"Other measurable returns"},{"level":2,"text":"Cost"},{"level":2,"text":"Usually called “project cost” or “project expense”, this variable is the money flowing out of the company"},{"level":2,"text":"Expenses will include direct and indirect expenses"},{"level":2,"text":"Labor"},{"level":2,"text":"Equipment"},{"level":2,"text":"Contracts"},{"level":2,"text":"Net Profit"},{"level":2,"text":"The difference between the benefit and the cost"},{"level":1,"text":"Business context, regulations, and environmental requirements are among many factors influencing project approvals"},{"level":1,"text":"Financial analysis involves assigning hard numbers to future events"},{"level":1,"text":"The further out we are trying to plan or assign numbers to something, the worse our accuracy is going to be"},{"level":1,"text":"It’s helpful to include a summary of your assumptions and risks in the financial plan section of the business case"},{"level":2,"text":"Assumptions"},{"level":2,"text":"Factors that you state as true in the calculations to present a simplified financial plan"},{"level":2,"text":"Risks are events that you think could happen"},{"level":2,"text":"Including risks with a higher likelihood of occurrence balances the optimism of business case assumptions"}]},{"id":"g14","part":2,"title":"ESG Factors","blocks":[{"level":1,"text":"Environmental, Social, and Governance (ESG) Factors"},{"level":2,"text":"Refer to a company’s actions and programs with intentions beyond simply making money and maximizing their profits"},{"level":1,"text":"Environmental Factors"},{"level":2,"text":"How the organization impacts the natural world"},{"level":2,"text":"Environmental considerations may include"},{"level":2,"text":"Landfill Consumption"},{"level":2,"text":"Waste Generation and Disposal Methods"},{"level":2,"text":"Pollution"},{"level":2,"text":"Habitat Protection or Destruction"},{"level":2,"text":"Resource Consumption"},{"level":1,"text":"Social Factors"},{"level":2,"text":"How the company develops relationships and treats people"},{"level":2,"text":"Employees"},{"level":2,"text":"People in the community"},{"level":2,"text":"Groups impacted by the company’s products and services"},{"level":1,"text":"Governance Factors"},{"level":2,"text":"How the company operates"},{"level":2,"text":"Policies"},{"level":2,"text":"Transparency"},{"level":2,"text":"Structure"},{"level":1,"text":"A company must apply environmental, social, and governance factors when conducting their business as usual operations and their temporary projects"},{"level":1,"text":"Form relationships with the organization’s internal legal team"},{"level":1,"text":"Corporate Identity"},{"level":2,"text":"Includes the vision, mission statement, values, and brand of the company"},{"level":2,"text":"The vision, mission, and values are the identity the company shares via published statements that should reflect the company’s spirit"},{"level":2,"text":"A company’s brand describes how people actually perceive the company"},{"level":2,"text":"It might include tangible items"},{"level":2,"text":"Symbols"},{"level":2,"text":"Color Schemes"},{"level":2,"text":"Memorable Slogan or Spokesperson"},{"level":2,"text":"It might also include intangible items"},{"level":2,"text":"General sense of how they feel about the company"},{"level":2,"text":"General characteristics or traits"},{"level":2,"text":"Company’s societal influence"},{"level":2,"text":"The brand is influenced by the company’s consumers, employees, community members, and business partners, and not just the PR department"},{"level":1,"text":"Incorporate ESG factors into the project design and decision-making throughout the life of the project Methodologies and Frameworks"}]},{"id":"g15","part":3,"title":"Methodologies and Frameworks","blocks":[{"level":1,"text":"There are many different kinds of methodologies and frameworks to manage projects"},{"level":1,"text":"The proper framework can simplify the project management process and amplify the project’s results"},{"level":1,"text":"Framework"},{"level":2,"text":"The processes, tasks, roles, and guiding principles that form the structure of completing work"},{"level":2,"text":"The framework significantly influences how a project moves from start to finish"},{"level":1,"text":"DevOps promotes continuous integration, continuous delivery, and continuous deployment (CI/CD)"},{"level":1,"text":"DevSecOps takes it a step further by incorporating security measures throughout the development process"},{"level":1,"text":"Scaled Agile Framework (SAFe)"},{"level":2,"text":"Methodology used to expand Agile practices across multiple teams in an organization"},{"level":2,"text":"SAFe is best suited for companies with projects involving multiple teams that need to communicate and collaborate effectively"},{"level":1,"text":"Software Development Life Cycle (SDLC)"},{"level":2,"text":"Flexible framework designed to produce high-quality, low-cost, and thoroughly tested software through continual improvement"},{"level":2,"text":"SDLC also relies heavily on thorough advance planning, which may not suit agile-focused teams"}]},{"id":"g16","part":3,"title":"Waterfall","blocks":[{"level":1,"text":"Waterfall Methodology"},{"level":2,"text":"A sequential development process that flows like a waterfall through all phases of a project"},{"level":2,"text":"Initially used in manufacturing, and eventually made its way to software development because it was in common use by that time, serving as an early starting point"},{"level":2,"text":"It follows a linear sequence"},{"level":1,"text":"6 Phases of Waterfall Methodology"},{"level":2,"text":"Requirements"},{"level":2,"text":"Define the requirements of the project"},{"level":2,"text":"Design"},{"level":2,"text":"Converts the requirements into actionable specifications"},{"level":2,"text":"Implementation"},{"level":2,"text":"Completes the work like writing code"},{"level":2,"text":"Testing"},{"level":2,"text":"Verifies that the work meets the requirements and quality specifications"},{"level":2,"text":"Delivery"},{"level":2,"text":"Also known as deployment, moves the product into production"},{"level":2,"text":"Maintenance"},{"level":2,"text":"Solves any issues that may arise"},{"level":1,"text":"Waterfall phases are displayed uniquely and differently since they cascade from the first stage to second to the third, and so on, until you reach the last phase"},{"level":1,"text":"Advantages of Waterfall"},{"level":2,"text":"Waterfall framework is the simplest framework that you will be tested on and is easy to understand and deploy"},{"level":2,"text":"The documentation required for these projects is very thorough"},{"level":1,"text":"Disadvantages of Waterfall"},{"level":2,"text":"Waterfall methodology is not very flexible"},{"level":2,"text":"The plan is designed up front and changes or revisions down the line are often costly in time, money, or other resources"},{"level":2,"text":"Makes change management very expensive to conduct in a waterfall- based project"},{"level":1,"text":"When would we use waterfall?"},{"level":2,"text":"Fixed requirements with no unknowns"},{"level":2,"text":"Change costs are very high"},{"level":2,"text":"Short and simple"},{"level":1,"text":"Waterfall project management is a linear methodology"},{"level":2,"text":"Advantages"},{"level":2,"text":"Simplicity"},{"level":2,"text":"Ease of understanding"},{"level":2,"text":"Thorough documentation"},{"level":2,"text":"Disadvantages"},{"level":2,"text":"Inflexibility"},{"level":2,"text":"High change management costs"}]},{"id":"g17","part":3,"title":"Agile","blocks":[{"level":1,"text":"Agile Methodology"},{"level":2,"text":"A project management approach that involves breaking the project into phases and emphasizes continuous collaboration and improvement"},{"level":1,"text":"Differences between Waterfall and Agile"},{"level":2,"text":"Waterfall"},{"level":2,"text":"Structured and delivers value at the end"},{"level":2,"text":"Big design upfront approach"},{"level":2,"text":"Best with no unknowns"},{"level":2,"text":"Agile"},{"level":2,"text":"Flexible and delivers value early and often"},{"level":2,"text":"Iterative and incremental"},{"level":2,"text":"Adaptable to change"},{"level":1,"text":"Iterative Development"},{"level":2,"text":"A software development approach that emphasizes the continuous refinement and improvement of a system or product"},{"level":2,"text":"The main goal of each iteration is to identify issues, make improvements, and incorporate feedback from users or stakeholders"},{"level":2,"text":"Key Benefits"},{"level":2,"text":"Ability to respond quickly to changing requirements or emerging user needs"},{"level":2,"text":"Opportunity for early and frequent user feedback"},{"level":1,"text":"Incremental Development"},{"level":2,"text":"A software development approach that focuses on delivering small, functional parts of a system or product in a step-by-step manner"},{"level":2,"text":"Key Benefits"},{"level":2,"text":"Reduced risk and predictable project outcomes"},{"level":2,"text":"Developers manage complexity, minimize errors, and maintain a higher level of control over the development process"},{"level":2,"text":"Allows for faster delivery of new features"},{"level":1,"text":"When a team used iterative and incremental development, they would build one feature at a time"},{"level":1,"text":"Agile is adaptable with shorter release cycles, and waterfall will require more information and requirements"},{"level":2,"text":"Its flexibility can lead to scope creep and missed deadlines"},{"level":2,"text":"It can lead to less documentation"},{"level":1,"text":"ERP system may not be a good agile candidate"},{"level":1,"text":"Advantages of Agile"},{"level":2,"text":"Adaptability"},{"level":2,"text":"Shorter release cycles"},{"level":2,"text":"Higher quality results"},{"level":1,"text":"Disadvantages of Agile"},{"level":2,"text":"Potential scope creep"},{"level":2,"text":"Missed deadlines"},{"level":2,"text":"Less documentation"}]},{"id":"g18","part":3,"title":"Scrum","blocks":[{"level":1,"text":"Scrum is the most common agile framework; it delivers iterative and adaptive value while intentionally covering only the barest requirements"},{"level":2,"text":"It uses empiricism and lean thinking to continuously improve results"},{"level":2,"text":"Empiricism encourages teams to make decisions based on what they see and know"},{"level":2,"text":"It is the practice of relying on observation and experimentation"},{"level":2,"text":"In other words, look at what happened instead of trying to predict what might happen"},{"level":2,"text":"Lean Thinking"},{"level":2,"text":"It is focused on driving improved efficiency by reducing waste, redundancy, and other unnecessary work within a given project"},{"level":1,"text":"5 Key Values of Scrum"},{"level":2,"text":"Commitment"},{"level":2,"text":"Focus"},{"level":2,"text":"Openness"},{"level":2,"text":"Respect"},{"level":2,"text":"Courage"},{"level":1,"text":"3 Fundamental Pillars of Scrum"},{"level":2,"text":"Transparency"},{"level":2,"text":"Ensures that all team members have a clear understanding of the project’s progress, goals, and any challenges faced"},{"level":2,"text":"Inspection"},{"level":2,"text":"Involves regularly reviewing and assessing the work being done, as well as the processes used by the team"},{"level":2,"text":"Adaptation"},{"level":2,"text":"The process of making necessary adjustments in response to the findings from the inspection"},{"level":1,"text":"4 Basic Steps of Scrum Process"},{"level":2,"text":"Product owner prioritizes work into a product backlog"},{"level":2,"text":"Scrum team selects the top items in that backlog"},{"level":2,"text":"Scrum team and stakeholders review the sprint results"},{"level":2,"text":"Steps repeat as long as the product backlog exists"},{"level":1,"text":"4 Roles in Scrum"},{"level":2,"text":"Scrum Team"},{"level":2,"text":"Group of people who work together to deliver increments of value"},{"level":2,"text":"Product Owner"},{"level":2,"text":"Creates, maintains, and owns the product backlog"},{"level":2,"text":"Scrum Master"},{"level":2,"text":"The team’s coach which helps the team, product owner, and organization improve the implementation of scrum"},{"level":2,"text":"Developer"},{"level":2,"text":"Describes the remaining team members and isn’t exclusive to software engineers"},{"level":1,"text":"The scrum master and project manager are not the same role"},{"level":1,"text":"Key Artifacts and Terms of Scrum"},{"level":2,"text":"Product Backlog"},{"level":2,"text":"An ordered list of product changes or enhancements"},{"level":2,"text":"Product Goal"},{"level":2,"text":"Describes the product’s longer-term target, and the product backlog should deliver the product goal"},{"level":2,"text":"Sprint Backlog"},{"level":2,"text":"Includes what the team will do, why they think it is important, and how they will get it done"},{"level":2,"text":"Sprint Goal"},{"level":2,"text":"Summarizes the value of the sprint"},{"level":2,"text":"Increment"},{"level":2,"text":"A complete body of work that meets the definition of done and moves toward the product goal"},{"level":1,"text":"A sprint can have one or many increments"},{"level":2,"text":"Every increment needs a definition of done to create a shared understanding of what it takes to move forward"},{"level":1,"text":"Different Scrum Events"},{"level":2,"text":"Sprint"},{"level":2,"text":"Scrum iteration and the container for all other Scrum events"},{"level":2,"text":"Sprint Planning"},{"level":2,"text":"Lasts no more than eight hours for one-month sprints, and even less for shorter sprints"},{"level":2,"text":"Daily Scrum"},{"level":2,"text":"Where the developers meet to review progress toward the sprint goal and then plan the next 24 hours of work"},{"level":2,"text":"Sprint Review"},{"level":2,"text":"Uncovers issues early when they are small and easy to fix, reveals previously unknown development ideas, or confirms that the team is on track"},{"level":2,"text":"Sprint Retrospective"},{"level":2,"text":"Occurs when the team inspects how they worked in the past sprint and identifies improvement opportunities"},{"level":2,"text":"Retrospective focuses on the Scrum team and how they can improve how they work together"},{"level":1,"text":"Advantage of Scrum"},{"level":2,"text":"Scrum is flexible and can be used across any industry, and its short cycles allow for responsive learning and complex problem solving"},{"level":1,"text":"Disadvantages of Scrum"},{"level":2,"text":"Scrum relies on the organization to respect the product owner’s decisions about the backlog and priorities"},{"level":2,"text":"Scrum’s framework is designed for a single, high-performing and cross functional team, which means that less-experienced teams may struggle and scaling up to larger groups might be difficult"},{"level":1,"text":"Scrum is best suited for highly cohesive, cross-functional teams that are focused on continual improvement"},{"level":1,"text":"Scrum methodology is a lightweight, customer-centric Agile framework that focuses on iterative and adaptive value"}]},{"id":"g19","part":3,"title":"Kanban","blocks":[{"level":1,"text":"Kanban is used to control work in progress levels, known as WIP levels, and manage workflows in software and business processes"},{"level":1,"text":"6 Core Practices of Kanban"},{"level":2,"text":"Visualizing work"},{"level":2,"text":"Create a Kanban board that shows the specific phases that work moves through on your team"},{"level":2,"text":"Limit work in progress"},{"level":2,"text":"Prevents team members from getting overwhelmed and helps increase productivity and degradation of product quality"},{"level":2,"text":"Make policies explicit"},{"level":2,"text":"Clearly define how work gets completed and moves from one phase to another"},{"level":2,"text":"Manage flow"},{"level":2,"text":"This embraces the roots of lean manufacturing and reduces waste in the system"},{"level":2,"text":"Implement feedback loops"},{"level":2,"text":"You bake feedback directly into the system and stay informed about performance"},{"level":2,"text":"Improve collaboratively while evolving experimentally"},{"level":2,"text":"This means that we need to use the scientific method to test ideas and measure the results in the Kanban signals"},{"level":1,"text":"Kanban’s goal is to start now and keep improving"},{"level":2,"text":"Its most recognizable feature is the Kanban board"},{"level":2,"text":"Work moves through three basic phases: To Do, In Progress, and Done"},{"level":1,"text":"Four-Part Workflow of Kanban"},{"level":2,"text":"The product owner prioritizes and orders the backlog"},{"level":2,"text":"A team member selects the top-ordered item in the backlog and pulls it into progress"},{"level":2,"text":"The team moves the work item through the workflow, keeping within the work in progress limits"},{"level":2,"text":"When the team is ready to start new work, they select the next item in the backlog"},{"level":1,"text":"Differences of Scrum and Kanban"},{"level":2,"text":"Scrum"},{"level":2,"text":"Helps teams solve complicated issues"},{"level":2,"text":"Better for unpredictable work"},{"level":2,"text":"Kanban"},{"level":2,"text":"Helps teams focus on a reasonable amount of work"},{"level":2,"text":"Excels at most routine tasks"},{"level":1,"text":"Scrum teams often use Kanban boards to visualize their work"},{"level":1,"text":"Kanban teams use demonstrations and retrospectives to gather feedback and improve their processes"},{"level":1,"text":"Agile teams are even classified as Scrum, Kanban, or Scrumban"},{"level":1,"text":"Advantages of Kanban"},{"level":2,"text":"Kanban is the simplest agile framework to learn and can be applied to any industry"},{"level":2,"text":"It’s lightweight and focuses on routine work over iteration planning"},{"level":1,"text":"Disadvantages of Kanban"},{"level":2,"text":"Kanban can be less effective if teams are oversized or have high turnover"},{"level":2,"text":"Inaccuracies or changes between work items can disrupt the team’s focus, and cycle times may stretch out in the absence of set iterations, if performance is not properly managed"},{"level":1,"text":"Kanban is most effective for teams that have a backlog which changes often"},{"level":1,"text":"Kanban is an agile methodology that originated in lean manufacturing and is now applied to software development and other business processes"},{"level":1,"text":"Kanban and Scrum solve different problems and can be combined in some project into what is referred to as “Scrumban”"}]},{"id":"g20","part":3,"title":"Extreme Programming","blocks":[{"level":1,"text":"Extreme Programming (or XP) is another type of agile framework designed specifically for software development"},{"level":2,"text":"It aims to create a higher quality of life for the developer and better software for the customer"},{"level":2,"text":"It believes in the 40-hour workweek alongside frequent releases and customer centricity"},{"level":1,"text":"5 Values in the Extreme Programming Framework"},{"level":2,"text":"Communication"},{"level":2,"text":"Simplicity"},{"level":2,"text":"Feedback"},{"level":2,"text":"Respect"},{"level":2,"text":"Courage"},{"level":1,"text":"Extreme Programming methodology is also known for its unique principles and practices, like its emphasis on simplicity, promoting the solution that requires the least amount of coding or work"},{"level":1,"text":"3 Roles in Extreme Programming"},{"level":2,"text":"Customer"},{"level":2,"text":"Decides which features are needed and which are needed next"},{"level":2,"text":"Tracker"},{"level":2,"text":"Captures metrics, measures progress, and looks for improvement opportunities"},{"level":2,"text":"Coach"},{"level":2,"text":"Mentors team members on how to use Extreme Programming practices"},{"level":1,"text":"Most Common Practices in Extreme Programming"},{"level":2,"text":"Paired Programming"},{"level":2,"text":"Two software engineers work side by side to create code at once"},{"level":2,"text":"Ten-minute Building"},{"level":2,"text":"States that it should take less than 10 minutes to build, test, and deploy an entire system"},{"level":2,"text":"Continuous Integration"},{"level":2,"text":"Merges local code into the main repository at least a few times each day"},{"level":2,"text":"Test-First Programming"},{"level":2,"text":"A practice where developers write tests and then write code to pass the tests"},{"level":1,"text":"Extreme Programming adopts incremental design"},{"level":1,"text":"User stories are also implemented for communicating requirements"},{"level":2,"text":"The user’s needs are written in a short, descriptive format that conveys what the user wants and how it would help them"},{"level":1,"text":"Extreme Programming utilizes the concept of slack in its teams’ work schedules"},{"level":1,"text":"Advantages of Extreme Programming"},{"level":2,"text":"Very efficient"},{"level":2,"text":"Continuous integration, automation, and high rate of adaptability"},{"level":2,"text":"Team-focused practices and less project failures"},{"level":1,"text":"Disadvantages of Extreme Programming"},{"level":2,"text":"Has limited scope"},{"level":2,"text":"Code-centric practices can result in less optimal design"},{"level":2,"text":"Rapid pace of the work can cause stress"},{"level":2,"text":"Minimal documentation can hinder new team members’ understanding"},{"level":2,"text":"Relies on face-to-face interaction between team members and customers"},{"level":1,"text":"Extreme Programming is best employed by small, collocated teams who can manage unknown requirements with tight deadlines and who have test automation capabilities"}]},{"id":"g21","part":3,"title":"DevOps & DevSecOps","blocks":[{"level":1,"text":"DevOps"},{"level":2,"text":"A set of practices and tools that integrates and automates the work of software development and IT operations as a means for improving and shortening the systems development life cycle"},{"level":1,"text":"2 Categories of Software Delivery Process"},{"level":2,"text":"Software Development"},{"level":2,"text":"The development team designs and creates software across four workflow phases: plan, code, build, and test"},{"level":2,"text":"IT Operations"},{"level":2,"text":"The operations team would then deploy and support software across the four workflow phases of release, deploy, operate, and monitor"},{"level":1,"text":"DevOps eliminates the barrier between development and operations"},{"level":2,"text":"It includes the practices, tools, and culture of integrating development and operations and delivering work as often as needed"},{"level":1,"text":"DevOps increases throughput with automation and decreases bugs through early detection"},{"level":1,"text":"Continuous Integration (CI)"},{"level":2,"text":"Individual developers check their code into the main branch frequently, and automated tests run against the new code"},{"level":1,"text":"Continuous Delivery (CD)"},{"level":2,"text":"Prepares the code for release to production"},{"level":1,"text":"Continuous Deployment (CD)"},{"level":2,"text":"After integration, the continuous deployment process prepares the code for production release and deploys it to production"},{"level":1,"text":"Strengths of DevOps"},{"level":2,"text":"Great for teams that want to release code often"},{"level":2,"text":"Companies that want to limit friction"},{"level":2,"text":"Organizations with the resource to staff cross-functional teams"},{"level":1,"text":"Weaknesses of DevOps"},{"level":2,"text":"Require significant expertise and groups may struggle to find enough team members with the necessary skills"},{"level":2,"text":"Large or legacy systems with minimal automation will find it difficult to quickly switch over to DevOps"},{"level":1,"text":"DevOps is not a project management methodology, but it does control the software engineering process"},{"level":1,"text":"DevSecOps"},{"level":2,"text":"A development practice where security processes, such as security audits and testing, are automated and built in throughout the development process"},{"level":2,"text":"DevSecOps creates a shared responsibility where everybody on the team considers and owns the product’s security"},{"level":2,"text":"This decentralized security model requires a significant culture change"},{"level":2,"text":"We all need to understand security risks and utilize good operational security"},{"level":1,"text":"DevOps and DevSecOps are two approaches that integrate software development and IT operations to improve the systems development life cycle"},{"level":2,"text":"DevOps promotes continuous integration, continuous delivery, and continuous deployment (CI/CD), which enables faster delivery of high- quality code"},{"level":2,"text":"DevSecOps takes it a step further by incorporating security measures throughout the development process, creating a shared responsibility for security across the team"}]},{"id":"g22","part":3,"title":"Scaled Agile Framework","blocks":[{"level":1,"text":"Scaled Agile Framework (SAFe)"},{"level":2,"text":"A methodology used to expand Agile practices across multiple teams in an organization"},{"level":2,"text":"Strikes a balance between keeping teams aligned and preserving the team's autonomy"},{"level":1,"text":"Scaled Agile"},{"level":2,"text":"Term used to describe any methodology that expands agile tools to more than one team"},{"level":1,"text":"SAFe stands out as a comprehensive business agility framework and is free to use"},{"level":1,"text":"SAFe visualizes the prominent roles, practices, events, and artifacts on its interactive big picture"},{"level":1,"text":"Some key terms about SAFe"},{"level":2,"text":"Agile Team"},{"level":2,"text":"Teams are made of three to ten cross-functional people working together to deliver increments of value"},{"level":2,"text":"Agile Release Train (ART)"},{"level":2,"text":"Groups the related teams to simplify communication, planning, and schedules"},{"level":2,"text":"Iteration"},{"level":2,"text":"Agile methodology iteratively develops a product in fixed time increments"},{"level":2,"text":"Program Increment"},{"level":2,"text":"Similar to a quarterly cycle in extreme programming, and it serves as a longer-term planning cycle"},{"level":2,"text":"A program increment is a fixed-length increment that lasts 8-12 weeks instead of three months"},{"level":2,"text":"It is a shared timebox for all the teams on an ART"},{"level":2,"text":"Program Increment Planning"},{"level":2,"text":"Serves as the ART's planning event and is similar to sprint planning for a single Scrum team"},{"level":1,"text":"Strength of SAFe"},{"level":2,"text":"SAFe is great for bringing the benefits of agile to a larger organization and meets the scaling needs of scaling"},{"level":1,"text":"Weakness of SAFe"},{"level":2,"text":"Needs to add layers of terms, overhead, organization, and staff, which can grind the gears of Agile's ground-up approach"}]},{"id":"g23","part":3,"title":"Software Development Life Cycle","blocks":[{"level":1,"text":"Software Development Life Cycle (SDLC)"},{"level":2,"text":"A flexible software development framework that aims to produce high- quality, low-cost, and thoroughly tested software"},{"level":2,"text":"SLDC users incorporate best practices and lessons learned into the framework to be more efficient every subsequent cycle"},{"level":1,"text":"According to the CompTIA Project+ official textbook, there are 7 phases in the SDLC Framework"},{"level":2,"text":"Planning"},{"level":2,"text":"Where we outline the project and define the software’s scope and purpose"},{"level":2,"text":"Requirements"},{"level":2,"text":"We define the resources needed for the project and determine what the software needs to do"},{"level":2,"text":"Design & Prototyping"},{"level":2,"text":"Defines how the software needs to work, such as which programming language to use, which security protocols to use, and how the user interface behaves"},{"level":2,"text":"Development"},{"level":2,"text":"When the software is actually created"},{"level":2,"text":"Testing"},{"level":2,"text":"When tests are carried out to ensure the software performs as expected"},{"level":2,"text":"Deployment"},{"level":2,"text":"When the software enters production"},{"level":2,"text":"Operations and Maintenance"},{"level":2,"text":"When the software is supported as long as it remains in production"},{"level":1,"text":"The software development life cycle can be linear and sequential, iterative and incremental, or a combination both"},{"level":1,"text":"SDLC can be applied to multiple types of development models"},{"level":2,"text":"Waterfall"},{"level":2,"text":"The original SDLC model that was created to replicate existing waterfall methodologies"},{"level":2,"text":"Waterfall SDLC is suitable for predetermined technology stacks and short projects"},{"level":2,"text":"Iterative"},{"level":2,"text":"A hybrid approach of iterative and sequential models"},{"level":2,"text":"Spiral"},{"level":2,"text":"A risk-centric iterative model"},{"level":2,"text":"Spiral is the most complex and resource-intensive model, and the projects need to manage cost and scope aggressively"},{"level":2,"text":"Agile"},{"level":2,"text":"An iterative, customer-centric model"},{"level":2,"text":"Agile SDLC includes more customer feedback"},{"level":2,"text":"Companies seeking a fast time-to-market also use agile"},{"level":1,"text":"Strength of SDLC"},{"level":2,"text":"SDLC is a comprehensive framework and includes every necessary task"},{"level":1,"text":"Weakness of SDLC"},{"level":2,"text":"SDLC framework depends on time spent on thorough advance planning"}]},{"id":"g24","part":3,"title":"PRINCE2","blocks":[{"level":1,"text":"PRINCE2 is a process-based methodology that is most common in the UK, EU, Canada, and Australia"},{"level":2,"text":"It aims to control project management processes by creating clear project phases, clearly defining roles and responsibilities, and predefining tasks to manage the project life cycle"},{"level":1,"text":"PRINCE2 requires several roles"},{"level":2,"text":"Team Manager"},{"level":2,"text":"A member of the project management team who is focused on helping the project manager by supervising the teams and managing the quality of outputs"},{"level":2,"text":"Project Board"},{"level":2,"text":"Authorizes resources and funding, supports the project manager, and is ultimately responsible for the project"},{"level":2,"text":"The project board includes three roles: executive, senior user, and senior supplier"},{"level":2,"text":"Executive"},{"level":2,"text":"A member of upper management, represents the business perspective, the deciding member of the project board, and owns the project’s business case"},{"level":2,"text":"Senior User"},{"level":2,"text":"Represents the customer’s perspective"},{"level":2,"text":"Senior Supplier"},{"level":2,"text":"Represents the supplier or implementation partner’s perspective"},{"level":1,"text":"PRINCE2 started as a waterfall methodology and has since adopted a complementary agile model"},{"level":1,"text":"The key here lies in the best practices that it enforces which are the 7 principles, 7 themes, and 7 processes of the method"},{"level":1,"text":"PRINCE2 is highly flexible and one of its strengths is customization"},{"level":1,"text":"The 7 principles represent the philosophy of PRINCE2 and help guide decision making"},{"level":1,"text":"The themes represent the project manager's knowledge areas"},{"level":1,"text":"The 7 processes represent the activities that must happen throughout a project’s life cycle"},{"level":1,"text":"Starting up investigates the business case and determines a project’s viability"},{"level":2,"text":"Initiating defines the project’s aspects such as the scope, costs, time, risk, quality, and benefits"},{"level":1,"text":"PRINCE2 is very flexible and can be applied to pretty much any project"},{"level":2,"text":"It has constant communication between the project board, project manager, and project teams"},{"level":2,"text":"It is not a good fit for companies that do not emphasize documentation"},{"level":1,"text":"PRINCE2 is process-based project management methodology that is very popular in the United Kingdom, and is rapidly gaining acceptance in the United States"},{"level":2,"text":"It involves greater upper management involvement than other methodologies, fostering better resource management and reduced risk Comparing Waterfall and Agile"}]},{"id":"g25","part":3,"title":"Comparing Waterfall and Agile","blocks":[{"level":1,"text":"The starkest difference between waterfall and agile is flexibility"},{"level":1,"text":"Waterfall practitioners might refer to this flexibility as ambiguity, and agile supporters describe it as adaptability"}]},{"id":"g26","part":3,"title":"Product Ownership","blocks":[{"level":1,"text":"The project framework you select can affect how roles and responsibilities are assigned during a project"},{"level":1,"text":"Product Owners"},{"level":2,"text":"Work within agile teams and identify how to improve a product while being accountable for creating the most valuable product possible"},{"level":2,"text":"Responsibilities of Product Owner"},{"level":2,"text":"Creation of a valuable product"},{"level":2,"text":"Working within a fixed time, fixed cost and flexible scope"},{"level":2,"text":"Providing product direction and visions"},{"level":1,"text":"Project Managers"},{"level":2,"text":"Lead projects in any framework and do so as long as the project is active"},{"level":2,"text":"Responsibilities of Project Manager"},{"level":2,"text":"Managing project plans"},{"level":2,"text":"Schedule"},{"level":2,"text":"Initiation and closing documents"},{"level":2,"text":"Measuring the project’s progress"},{"level":2,"text":"Managing project risks"},{"level":2,"text":"Working within a fixed time, fixed cost, and fixed scope"},{"level":1,"text":"Product Managers"},{"level":2,"text":"Define the product strategy and create roadmaps to show how it will improve and change over time"},{"level":1,"text":"Both the project manager and product owner have overlapping responsibilities and unique shared interests"},{"level":2,"text":"They’re both responsible for communicating directly with stakeholders, leading their team, and maintaining work lists"},{"level":1,"text":"When leading a team"},{"level":2,"text":"Product owner shares guidance about the product’s purpose and vision"},{"level":2,"text":"Project manager builds support for the project and project approach"},{"level":1,"text":"When maintaining worklists"},{"level":2,"text":"Product owner maintains a product backlog"},{"level":2,"text":"Project manager uses a work breakdown structure (also called the WBS) or project backlog"},{"level":1,"text":"The product owner is not a manager"},{"level":1,"text":"Project managers need to manage teams and their work"},{"level":1,"text":"The product owner doesn’t get involved in the details of the work"},{"level":1,"text":"Agile teams are self-organizing and will take more of a leading role in breaking down work, regardless of if the work is for a product or project"},{"level":1,"text":"Collaboration with a product owner can make life easier for a project manager"},{"level":1,"text":"Preferably work with the product owner to build a consolidated product backlog that incorporates the project work"},{"level":1,"text":"If a team already has a product owner, they probably use an agile project management methodology"},{"level":1,"text":"Teams without a product owner could also use an agile project management approach"}]},{"id":"g27","part":3,"title":"Team Composition","blocks":[{"level":1,"text":"Agile"},{"level":2,"text":"Teams are small by design, with 3-10 members"},{"level":1,"text":"Waterfall"},{"level":2,"text":"Teams are large and can be any size"},{"level":1,"text":"Scaled Agile"},{"level":2,"text":"Creates a large team by grouping multiple small agile teams together"},{"level":1,"text":"Agile teams form a cross-functional group that stays with the project for the entire life cycle"},{"level":1,"text":"Members have to fill multiple roles and have broad experience"},{"level":1,"text":"A waterfall team assembles specialists to complete the work"},{"level":1,"text":"If keeping all team members for the entire project, select an agile framework"},{"level":1,"text":"When needing highly specialized individuals, consider using a Waterfall"}]},{"id":"g28","part":3,"title":"Communication","blocks":[{"level":1,"text":"Stakeholder Communication"},{"level":2,"text":"Stakeholder communication changes under different frameworks"},{"level":2,"text":"For example, in waterfall projects, the stakeholder provides comprehensive requirements at the start of the project"},{"level":2,"text":"Ensure customer's requirements, quality expectations, and needs are understood before moving on to the development of the project"},{"level":2,"text":"Agile projects engage the stakeholder throughout the entire project"},{"level":2,"text":"They require stakeholders with time and motivation to collaborate and receive a product that meets their needs"},{"level":1,"text":"Communication Channels"},{"level":2,"text":"In waterfall, the customer does not communicate directly with the developers"},{"level":2,"text":"In agile, the development team communicates directly with the customer to clarify requirements and share progress"},{"level":1,"text":"Communicating updates and changes"},{"level":2,"text":"Change frequency affects communication requirements as well"},{"level":2,"text":"Waterfall projects introduce few changes, whereas agile projects embrace change"},{"level":2,"text":"Agile reduces the chance of miscommunication"},{"level":2,"text":"The speed and volume of change require efficient communication"},{"level":2,"text":"Agile teams create a schedule every 1-4 weeks for sprint intervals and can incorporate changes at every planning session"}]},{"id":"g29","part":3,"title":"Requirements","blocks":[{"level":1,"text":"Requirements direct the project"},{"level":2,"text":"They dictate how the project's result looks, behaves, and is used"},{"level":1,"text":"The main differences between methodologies are when requirements are created"},{"level":2,"text":"In a waterfall project"},{"level":2,"text":"Collection of Requirements -> Product Creation -> Customer Review -> Maintenance Phase"},{"level":2,"text":"In an agile project"},{"level":2,"text":"Collection of Requirements -> Product Creation -> Customer Review"}]},{"id":"g30","part":3,"title":"Budget and Schedule","blocks":[{"level":1,"text":"Waterfall budgets are more rigid and predictable"},{"level":1,"text":"Agile budgets incorporate change and flexibility"},{"level":1,"text":"Projects with a strict budget would do well with a waterfall"},{"level":1,"text":"A project manager may need to communicate with customers to ensure they understand how costs accrue against the project’s deliverables"},{"level":2,"text":"It might also work with a team to ensure that their estimates accurately reflect their actual costs"},{"level":1,"text":"Agile projects can arrange budgets around high-level deliverables to create a hybrid approach"},{"level":1,"text":"Customers with a limited budget may prefer a waterfall project"},{"level":1,"text":"Customers who would rather spend more money on a tailored product would favor an agile approach"},{"level":1,"text":"Agile schedule is more flexible than waterfall schedule"},{"level":2,"text":"The schedule is loose and flexible"},{"level":2,"text":"The team plans one iteration at a time"},{"level":1,"text":"Waterfall schedule is more predictable than agile schedule"},{"level":2,"text":"The team plans the entire project schedule, including the timeline and the time needed for each phase and task of the project"}]},{"id":"g31","part":3,"title":"Environmental Factors","blocks":[{"level":1,"text":"Different Environmental Factors Between Waterfall and Agile"},{"level":2,"text":"Culture"},{"level":2,"text":"An agile team requires strong commitment, trust, and collaboration to achieve its ultimate value"},{"level":2,"text":"In waterfall, customers receive nearly finished products"},{"level":2,"text":"Developmental Processes"},{"level":2,"text":"When considering agile development maybe a customer can’t review increments"},{"level":2,"text":"Maybe manual testing and integrations make frequent builds expensive"},{"level":2,"text":"Industry Standards"},{"level":2,"text":"Highly regulated industries that require more documentation need a project management structure that will provide adequate traceability"},{"level":2,"text":"Companies that lean on documentation often choose waterfall Initiating the Project"}]});
